// APENAS QA LOCAL: importar em uma cópia temporária de vite.config.ts. Nunca usar no build de produção.
import { readFileSync } from 'node:fs';
const keys=['category_pipocas','category_fatias','category_cones','cone_prestigio','cone_dois_amores','cone_ferrero_rocher','slice_prestigio','slice_chocolatudo','popcorn_size_500ml','popcorn_size_750ml','popcorn_size_1l','popcorn_flavor_leitinho','drink_coca_cola_zero_220','drink_fanta_laranja_220','drink_guarana_antarctica_200','drink_coca_cola_350'];
const stock=['ninho','pacoca','coco_queimado'].flatMap(x=>['p','m','g'].map(size=>'trufada_'+x+'_'+size));
export default { name:'qa-local-only', enforce:'post', transform(code,id){if(id.endsWith('/lib/supabase-config.ts'))return code.replace(/const url = [\s\S]*?;\n/, 'const url = typeof window !== "undefined" ? window.location.origin : "http://127.0.0.1:4173";\n');},configureServer(server){server.middlewares.use((req,res,next)=>{
res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self' 'unsafe-inline' 'unsafe-eval'; style-src 'self' 'unsafe-inline' https://fonts.googleapis.com; font-src 'self' data: https://fonts.gstatic.com; img-src 'self' data:; connect-src 'self' ws:;");
if(req.url.startsWith('/__lod_qa')) {res.setHeader('Content-Type','text/html');res.end(`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Homologação local — Refrigerantes</title><style>body{margin:0;background:#17120f;color:#f7e7d3;font:14px system-ui}header{padding:12px 20px;background:#33251b}main{display:flex;align-items:flex-start;gap:24px;padding:16px;width:max-content}section{flex:none}iframe{border:1px solid #76573d;border-radius:12px;height:850px;background:#211810}h2{font:16px system-ui}</style><header>HOMOLOGAÇÃO LOCAL · Dados sintéticos · Sem pedidos, pagamentos ou eventos externos</header><main>${[320,375,390,430,1280].map(w=>`<section><h2>${w}px</h2><iframe title="Prévia ${w}px" name="qa-${w}" width="${w}" src="/?categoria=cones&qa_view=${w}"></iframe></section>`).join('')}</main></html>`);return;}
if(req.url.startsWith('/rest/v1/')) {const name=req.url.split('?')[0].split('/').pop();const status=JSON.parse(readFileSync(new URL('../.sites-runtime/qa-status.json',import.meta.url),'utf8'));
const data=name==='store_settings'?[{key:'orders_open',value:status.open!==false}]:name==='menu_availability'?[...keys,...stock].filter(k=>!status.missing?.includes(k)).map(item_key=>({item_key,status:status[item_key]||'available'})):name==='public_crocante_inventory'?stock.map(item_key=>({item_key,available:5})):name==='public_slice_preorder'?{active:false,remaining:0}:null;
res.setHeader('Content-Type','application/json');if(status.networkFailure){res.statusCode=503;res.end('{}');}else res.end(JSON.stringify(data));return;}
if(req.url.startsWith('/functions/v1/')){res.statusCode=503;res.end('{}');return;}
next();});}};
